import java.util.Vector;
import java.util.Collections;

public class Main {
    public static void main(String[] args) {

        // Try experimenting with Vector capacity!
        Vector<String> languages = new Vector<>(3, 2);
        System.out.println("Initial capacity: " + languages.capacity());

        languages.add("Java");
        languages.add("Python");
        languages.add("C++");
        languages.add("Kotlin");  // triggers resize

        System.out.println("After 4 adds, capacity: " + languages.capacity());
        System.out.println("Languages: " + languages);

        Collections.sort(languages);
        System.out.println("Sorted: " + languages);

        languages.trimToSize();
        System.out.println("After trimToSize, capacity: " + languages.capacity());
    }
}
